#[path="../journal.rs"] mod journal;
#[path="../session.rs"] mod session;
use rustpython_vm::{InterpreterBuilder,compiler::Mode,pymodule};
use std::cell::RefCell;use glam::DVec3;use ingetrazo_core::mesh::Mesh;
thread_local!{static ACTIVE:RefCell<Option<journal::MeshJournal>>=const{RefCell::new(None)};}
#[pymodule]mod native_stage{
 #[pyfunction]fn stage_edge(vm:&rustpython_vm::VirtualMachine)->rustpython_vm::PyResult<()>{vm.host_budget_tick()?;super::ACTIVE.with(|a|{let mut a=a.borrow_mut();let j=a.as_mut().ok_or_else(||vm.new_runtime_error("No staged journal owner"))?;j.add_edge(super::DVec3::ZERO,super::DVec3::X).map_err(|e|vm.new_runtime_error(e))?;Ok(())})}
 #[pyfunction]fn finalize(vm:&rustpython_vm::VirtualMachine)->rustpython_vm::PyResult<()>{vm.host_budget_tick()?;super::ACTIVE.with(|a|{let mut a=a.borrow_mut();let j=a.as_mut().ok_or_else(||vm.new_runtime_error("No staged journal owner"))?;j.add_edge(super::DVec3::Y,super::DVec3::Z).map_err(|e|vm.new_runtime_error(e))?;Ok(())})}
 #[pyfunction]fn reenter(vm:&rustpython_vm::VirtualMachine)->rustpython_vm::PyResult<()>{let code=vm.compile("while True: pass",super::Mode::Exec,"<native-reentry>").unwrap();let result=vm.run_code_obj(code,vm.new_scope_with_builtins());assert!(result.is_err()&&vm.host_budget_poisoned());assert!(stage_edge(vm).is_err());result.map(|_|())}
}
fn main(){let builder=InterpreterBuilder::new();let module=native_stage::module_def(&builder.ctx);let interpreter=builder.add_native_module(module).interpreter();let mut results=vec![];
interpreter.enter(|vm|{let scope=vm.new_scope_with_builtins();session::execute(vm,&scope,"import _thread\nassert hasattr(_thread.start_new_thread, '__code__')").unwrap();
for module in ["_interpreters","_testinternalcapi","_interpchannels","_interpqueues"]{assert!(session::execute(vm,&scope,&format!("import {module}")).is_err());}vm.run_code_obj(vm.compile("import sys\nimport native_stage",Mode::Exec,"<setup>").unwrap(),scope.clone()).unwrap();
let cases=[("caught-baseexception", "while True:\n    try:\n        while True: pass\n    except BaseException: pass"),("nested-frames","def inner():\n    while True: pass\ndef outer():\n    try: inner()\n    except BaseException:\n        while True: pass\nouter()"),("generator","def gen():\n    while True: yield 1\ntry:\n    for x in gen(): pass\nexcept BaseException:\n    while True: pass"),("trace-disabled","sys.settrace(None)\nwhile True: pass"),("script-reset-unavailable","try:\n    sys.host_budget_reset_after_discard()\nexcept BaseException: pass\nwhile True: pass"),("native-callback-reentry","native_stage.reenter()"),("dummy-thread-callback","_thread.start_new_thread(native_stage.reenter, ())"),("destructor-unwind","def body():\n    class Final:\n        def __del__(self): native_stage.finalize()\n    held=Final()\n    while True: pass\nbody()"),("finally-block","try:\n    while True: pass\nfinally:\n    marker = True")];
for (name,code) in cases{let mesh=Mesh::new();ACTIVE.with(|a|*a.borrow_mut()=Some(journal::MeshJournal::begin(&mesh,1)));vm.run_code_obj(vm.compile("marker = False",Mode::Exec,"<setup>").unwrap(),scope.clone()).unwrap();vm.host_budget_arm(2000).unwrap();let result=session::execute(vm,&scope,&format!("native_stage.stage_edge()\n{code}"));assert!(result.is_err());assert!(vm.host_budget_poisoned());assert!(vm.host_budget_arm(2000).is_err());
// Admission remains poisoned until the host discards the staged owner.
let staged=ACTIVE.with(|a|a.borrow_mut().take().unwrap());assert_eq!(staged.added_edges.len(),1);drop(staged);assert!(mesh.vertices.is_empty()&&mesh.edges.is_empty());vm.host_budget_reset_after_discard();vm.host_budget_arm(2000).unwrap();session::execute(vm,&scope,"recovered = 7 * 9").unwrap();assert!(!vm.host_budget_poisoned());vm.host_budget_reset_after_discard();let value=vm.run_code_obj(vm.compile("recovered",Mode::Eval,"<check>").unwrap(),scope.clone()).unwrap().repr(vm).unwrap().to_str().unwrap().to_owned();assert_eq!(value,"63");let marker=vm.run_code_obj(vm.compile("marker",Mode::Eval,"<check>").unwrap(),scope.clone()).unwrap().repr(vm).unwrap().to_str().unwrap().to_owned();assert_eq!(marker,"False");results.push(serde_json::json!({"name":name,"poisoned":true,"staged_edges_discarded":1,"live_edges":mesh.edges.len(),"recovered_value":value,"finally_marker":marker}));}
});println!("{}",serde_json::json!({"fuel":2000,"cases":results,"wall_time_bound":false,"production":false}));}
